// ======================================================
// INTERPRETAR RESPUESTA DE OPENAI
// Convierte la salida del modelo en un objeto JSON limpio.
// Conserva null cuando un dato no fue identificado.
// ======================================================

const respuesta = $json;

// ------------------------------------------------------
// FUNCIONES AUXILIARES
// ------------------------------------------------------

function estaVacio(valor) {
  return (
    valor === null ||
    valor === undefined ||
    (typeof valor === 'string' && valor.trim() === '')
  );
}

function textoONull(valor) {
  if (estaVacio(valor)) {
    return null;
  }

  return String(valor).trim();
}

function numeroONull(valor) {
  if (estaVacio(valor)) {
    return null;
  }

  // Si ya es un número válido, se conserva.
  if (typeof valor === 'number') {
    return Number.isFinite(valor) ? valor : null;
  }

  let texto = String(valor).trim();

  // Elimina símbolos y espacios, pero conserva signos,
  // puntos y comas para intentar interpretar el número.
  texto = texto.replace(/[^\d.,-]/g, '');

  if (!texto) {
    return null;
  }

  /*
   * Normalización básica:
   * 121.000,50  → 121000.50
   * 121,000.50  → 121000.50
   * 121000,50   → 121000.50
   */

  const tienePunto = texto.includes('.');
  const tieneComa = texto.includes(',');

  if (tienePunto && tieneComa) {
    const ultimoPunto = texto.lastIndexOf('.');
    const ultimaComa = texto.lastIndexOf(',');

    if (ultimaComa > ultimoPunto) {
      // Formato habitual en español: 121.000,50
      texto = texto.replace(/\./g, '').replace(',', '.');
    } else {
      // Formato habitual en inglés: 121,000.50
      texto = texto.replace(/,/g, '');
    }
  } else if (tieneComa && !tienePunto) {
    // Una coma se interpreta como separador decimal.
    texto = texto.replace(',', '.');
  }

  const numero = Number(texto);

  return Number.isFinite(numero) ? numero : null;
}

function enteroONull(valor) {
  const numero = numeroONull(valor);

  if (numero === null) {
    return null;
  }

  return Math.round(numero);
}

function limpiarBloqueJson(texto) {
  return texto
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

// ------------------------------------------------------
// 1. LOCALIZAR EL CONTENIDO DEVUELTO POR OPENAI
// ------------------------------------------------------

let contenido = null;

// Caso 1: respuesta directa en output_text.
if (
  typeof respuesta.output_text === 'string' &&
  respuesta.output_text.trim()
) {
  contenido = respuesta.output_text;
}

// Caso 2: estructura habitual del endpoint /v1/responses.
if (contenido === null && Array.isArray(respuesta.output)) {
  for (const elemento of respuesta.output) {
    if (!Array.isArray(elemento.content)) {
      continue;
    }

    const salidaTexto = elemento.content.find(
      (item) =>
        item &&
        (item.type === 'output_text' || item.type === 'text') &&
        typeof item.text === 'string',
    );

    if (salidaTexto) {
      contenido = salidaTexto.text;
      break;
    }
  }
}

// Caso 3: algunas respuestas pueden venir dentro de body.
if (
  contenido === null &&
  respuesta.body &&
  typeof respuesta.body.output_text === 'string'
) {
  contenido = respuesta.body.output_text;
}

// Caso 4: respuesta simulada ya convertida en objeto.
if (
  contenido === null &&
  respuesta.factura &&
  typeof respuesta.factura === 'object' &&
  !Array.isArray(respuesta.factura)
) {
  contenido = respuesta.factura;
}

// Caso 5: el propio item ya contiene directamente
// las propiedades esperadas de la factura.
if (
  contenido === null &&
  (
    Object.prototype.hasOwnProperty.call(respuesta, 'numero_factura') ||
    Object.prototype.hasOwnProperty.call(respuesta, 'cuit_proveedor') ||
    Object.prototype.hasOwnProperty.call(respuesta, 'total')
  )
) {
  contenido = respuesta;
}

if (contenido === null) {
  throw new Error(
    'No se encontró texto ni un objeto de factura en la respuesta de OpenAI.',
  );
}

// ------------------------------------------------------
// 2. CONVERTIR EL CONTENIDO EN JSON
// ------------------------------------------------------

let factura;

if (
  typeof contenido === 'object' &&
  contenido !== null &&
  !Array.isArray(contenido)
) {
  factura = contenido;
} else {
  const textoLimpio = limpiarBloqueJson(String(contenido));

  try {
    factura = JSON.parse(textoLimpio);
  } catch (error) {
    throw new Error(
      `OpenAI devolvió un JSON inválido: ${error.message}. ` +
      `Contenido recibido: ${textoLimpio.slice(0, 500)}`,
    );
  }
}

if (
  typeof factura !== 'object' ||
  factura === null ||
  Array.isArray(factura)
) {
  throw new Error(
    'La respuesta de OpenAI no contiene un objeto JSON válido de factura.',
  );
}

// Algunos modelos podrían envolver el resultado en una propiedad.
if (
  factura.factura &&
  typeof factura.factura === 'object' &&
  !Array.isArray(factura.factura)
) {
  factura = factura.factura;
}

// ------------------------------------------------------
// 3. NORMALIZAR LOS CAMPOS ESPERADOS
// ------------------------------------------------------

const facturaInterpretada = {
  proveedor: textoONull(factura.proveedor),

  cuit_proveedor: textoONull(factura.cuit_proveedor),

  numero_factura: textoONull(factura.numero_factura),

  fecha_emision: textoONull(factura.fecha_emision),

  fecha_vencimiento: textoONull(factura.fecha_vencimiento),

  moneda: textoONull(factura.moneda),

  subtotal: numeroONull(factura.subtotal),

  iva: numeroONull(factura.iva),

  otros_impuestos: numeroONull(factura.otros_impuestos),

  total: numeroONull(factura.total),

  orden_compra: textoONull(factura.orden_compra),

  concepto: textoONull(factura.concepto),

  categoria_gasto: textoONull(factura.categoria_gasto),

  resumen_ia: textoONull(factura.resumen_ia),

  confianza_extraccion: enteroONull(
    factura.confianza_extraccion,
  ),
};

// ------------------------------------------------------
// 4. DEVOLVER EL RESULTADO
// ------------------------------------------------------

return {
  json: facturaInterpretada,
};

