// ======================================================
// VALIDACIÓN DOCUMENTAL DE LA FACTURA
// Este nodo valida únicamente los datos extraídos por IA.
// Todavía no valida proveedor, OC ni duplicados contra Airtable.
// ======================================================

const factura = { ...$json };

const errores = [];
const advertencias = [];

// Umbral propuesto para enviar la factura a revisión.
// Puede modificarse después de las pruebas.
const UMBRAL_CONFIANZA = 80;

// Diferencia máxima admitida entre el total informado
// y la suma de subtotal + impuestos.
const TOLERANCIA_IMPORTES = 0.05;

const CATEGORIAS_VALIDAS = [
  'Servicios',
  'Tecnología',
  'Infraestructura',
  'Logística',
  'Marketing',
  'Capacitación',
  'Compras generales',
  'Mantenimiento',
  'Impuestos',
  'Viajes',
  'Otros',
];

const MONEDAS_VALIDAS = ['ARS', 'USD', 'EUR'];

// ------------------------------------------------------
// FUNCIONES AUXILIARES
// ------------------------------------------------------

function estaVacio(valor) {
  return (
    valor === null ||
    valor === undefined ||
    (typeof valor === 'string' && valor.trim() === '')
  );
}

function convertirNumero(valor) {
  if (estaVacio(valor)) {
    return null;
  }

  const numero = Number(valor);

  return Number.isFinite(numero) ? numero : null;
}

function fechaValida(valor) {
  if (estaVacio(valor)) {
    return false;
  }

  const texto = String(valor).trim();

  // Verifica el formato YYYY-MM-DD.
  if (!/^\d{4}-\d{2}-\d{2}$/.test(texto)) {
    return false;
  }

  const [anio, mes, dia] = texto.split('-').map(Number);
  const fecha = new Date(Date.UTC(anio, mes - 1, dia));

  // Verifica que la fecha exista realmente.
  return (
    fecha.getUTCFullYear() === anio &&
    fecha.getUTCMonth() === mes - 1 &&
    fecha.getUTCDate() === dia
  );
}

function normalizarMoneda(valor) {
  if (estaVacio(valor)) {
    return null;
  }

  const moneda = String(valor)
    .trim()
    .toUpperCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  const equivalencias = {
    ARS: 'ARS',
    PESO: 'ARS',
    PESOS: 'ARS',
    'PESO ARGENTINO': 'ARS',
    'PESOS ARGENTINOS': 'ARS',

    USD: 'USD',
    DOLAR: 'USD',
    DOLARES: 'USD',
    'DOLAR ESTADOUNIDENSE': 'USD',

    EUR: 'EUR',
    EURO: 'EUR',
    EUROS: 'EUR',
  };

  return equivalencias[moneda] ?? moneda;
}

function normalizarCuit(valor) {
  if (estaVacio(valor)) {
    return null;
  }

  return String(valor).replace(/\D/g, '');
}

// ------------------------------------------------------
// NORMALIZACIÓN DE DATOS
// ------------------------------------------------------

factura.proveedor = estaVacio(factura.proveedor)
  ? null
  : String(factura.proveedor).trim();

factura.cuit_proveedor = estaVacio(factura.cuit_proveedor)
  ? null
  : String(factura.cuit_proveedor).trim();

factura.numero_factura = estaVacio(factura.numero_factura)
  ? null
  : String(factura.numero_factura).trim();

factura.fecha_emision = estaVacio(factura.fecha_emision)
  ? null
  : String(factura.fecha_emision).trim();

factura.fecha_vencimiento = estaVacio(factura.fecha_vencimiento)
  ? null
  : String(factura.fecha_vencimiento).trim();

factura.moneda = normalizarMoneda(factura.moneda);

factura.subtotal = convertirNumero(factura.subtotal);
factura.iva = convertirNumero(factura.iva);
factura.otros_impuestos = convertirNumero(factura.otros_impuestos);
factura.total = convertirNumero(factura.total);

factura.orden_compra = estaVacio(factura.orden_compra)
  ? null
  : String(factura.orden_compra).trim();

factura.concepto = estaVacio(factura.concepto)
  ? null
  : String(factura.concepto).trim();

factura.categoria_gasto = estaVacio(factura.categoria_gasto)
  ? null
  : String(factura.categoria_gasto).trim();

factura.resumen_ia = estaVacio(factura.resumen_ia)
  ? null
  : String(factura.resumen_ia).trim();

factura.confianza_extraccion = convertirNumero(
  factura.confianza_extraccion,
);

// ------------------------------------------------------
// VALIDACIÓN DE CAMPOS OBLIGATORIOS
// ------------------------------------------------------

if (estaVacio(factura.proveedor)) {
  errores.push('Proveedor no identificado');
}

if (estaVacio(factura.cuit_proveedor)) {
  errores.push('CUIT del proveedor no identificado');
} else {
  const cuitNormalizado = normalizarCuit(factura.cuit_proveedor);

  if (cuitNormalizado.length !== 11) {
    errores.push('El CUIT del proveedor no tiene 11 dígitos');
  }
}

if (estaVacio(factura.numero_factura)) {
  errores.push('Número de factura no identificado');
}

if (estaVacio(factura.fecha_emision)) {
  errores.push('Fecha de emisión no identificada');
} else if (!fechaValida(factura.fecha_emision)) {
  errores.push('La fecha de emisión no tiene un formato válido');
}

// Fecha de vencimiento: se valida solo cuando está informada.
if (
  !estaVacio(factura.fecha_vencimiento) &&
  !fechaValida(factura.fecha_vencimiento)
) {
  errores.push('La fecha de vencimiento no tiene un formato válido');
}

if (estaVacio(factura.moneda)) {
  errores.push('Moneda no identificada');
} else if (!MONEDAS_VALIDAS.includes(factura.moneda)) {
  errores.push(
    `Moneda no admitida: ${factura.moneda}. Valores permitidos: ARS, USD o EUR`,
  );
}

if (factura.total === null) {
  errores.push('Importe total no identificado o inválido');
} else if (factura.total <= 0) {
  errores.push('El importe total debe ser mayor que cero');
}

if (estaVacio(factura.orden_compra)) {
  errores.push('Orden de compra no identificada');
}

// ------------------------------------------------------
// VALIDACIÓN DE IMPORTES
// ------------------------------------------------------

if (factura.subtotal !== null && factura.subtotal < 0) {
  errores.push('El subtotal no puede ser negativo');
}

if (factura.iva !== null && factura.iva < 0) {
  errores.push('El IVA no puede ser negativo');
}

if (
  factura.otros_impuestos !== null &&
  factura.otros_impuestos < 0
) {
  errores.push('Los otros impuestos no pueden ser negativos');
}

// Se compara el total únicamente cuando todos los componentes
// necesarios fueron identificados.
if (
  factura.subtotal !== null &&
  factura.iva !== null &&
  factura.otros_impuestos !== null &&
  factura.total !== null
) {
  const totalCalculado =
    factura.subtotal +
    factura.iva +
    factura.otros_impuestos;

  const diferencia = Math.abs(totalCalculado - factura.total);

  if (diferencia > TOLERANCIA_IMPORTES) {
    errores.push(
      `El total informado (${factura.total}) no coincide con subtotal más impuestos (${totalCalculado})`,
    );
  }
} else {
  advertencias.push(
    'No fue posible comprobar la suma de subtotal e impuestos porque falta al menos uno de los importes',
  );
}

// ------------------------------------------------------
// VALIDACIÓN DE CATEGORÍA
// ------------------------------------------------------

if (estaVacio(factura.categoria_gasto)) {
  advertencias.push('Categoría de gasto no identificada');
} else if (!CATEGORIAS_VALIDAS.includes(factura.categoria_gasto)) {
  errores.push(
    `Categoría de gasto no admitida: ${factura.categoria_gasto}`,
  );
}

// ------------------------------------------------------
// VALIDACIÓN DE CONFIANZA DE EXTRACCIÓN
// ------------------------------------------------------

if (factura.confianza_extraccion === null) {
  errores.push('La IA no informó el nivel de confianza');
} else if (
  factura.confianza_extraccion < 0 ||
  factura.confianza_extraccion > 100
) {
  errores.push(
    'El nivel de confianza debe estar comprendido entre 0 y 100',
  );
} else if (factura.confianza_extraccion < UMBRAL_CONFIANZA) {
  errores.push(
    `Confianza de extracción inferior al umbral de ${UMBRAL_CONFIANZA}%`,
  );
}

// ------------------------------------------------------
// RESULTADO
// ------------------------------------------------------

const requiereRevision = errores.length > 0;

return {
  json: {
    ...factura,

    requiere_revision: requiereRevision,

    motivo_revision: requiereRevision
      ? errores.join(' | ')
      : '',

    advertencias_validacion: advertencias.join(' | '),

    cantidad_errores_validacion: errores.length,

    cantidad_advertencias_validacion: advertencias.length,

    resultado_validacion_documental: requiereRevision
      ? 'Con excepciones'
      : 'Validación documental superada',

    estado_sugerido: requiereRevision
      ? 'Requiere revisión'
      : 'Procesado por IA',
  },
};

